


const mongoose = require("mongoose");

const appBackgroundEventSchema = new mongoose.Schema(
  {
    // Unique ID generated by Flutter for each background event.
    // Prevents counting the same event more than once.
    eventId: {
      type: String,
      required: true,
      trim: true,
    },

    backgroundAt: {
      type: Date,
      required: true,
    },
  },
  {
    _id: false,
  }
);

const attemptSchema = new mongoose.Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },

    contestId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Contest",
      required: true,
      index: true,
    },

    dayNumber: {
      type: Number,
      required: true,
    },

    questionIds: [
      {
        type: mongoose.Schema.Types.ObjectId,
        ref: "Question",
      },
    ],

    answers: [
      {
        questionId: {
          type: mongoose.Schema.Types.ObjectId,
          ref: "Question",
        },

        answer: {
          type: String,
        },
      },
    ],

    startedAt: {
      type: Date,
    },

    expiresAt: {
      type: Date,
    },

    submittedAt: {
      type: Date,
    },

    status: {
      type: String,
      enum: ["started", "submitted", "expired"],
      default: "started",
    },

    score: {
      type: Number,
      default: 0,
    },

    totalMarks: {
      type: Number,
      default: 0,
    },

    // Total number of recorded app-background events.
    appBackgroundCount: {
      type: Number,
      default: 0,
      min: 0,
    },

    // Recent event history for auditing and troubleshooting.
    // The controller will keep this list limited to recent events.
    appBackgroundEvents: {
      type: [appBackgroundEventSchema],
      default: [],
    },

    lastAppBackgroundAt: {
      type: Date,
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

// One attempt per user, contest and contest day.
attemptSchema.index(
  {
    userId: 1,
    contestId: 1,
    dayNumber: 1,
  },
  {
    unique: true,
  }
);

module.exports = mongoose.model("Attempt", attemptSchema);
